import {mountAssetCombobox} from './asset-combobox.mjs';
import {demo,requireSession,markConnected,identity,api,keyed,can,departmentsFor} from './server-session.mjs';
import {ServerResources,resourceAllows,assetPayload} from './server-resources.mjs?v=backend-complete-20261104.4';
import {mountReports} from './server-reports.mjs?v=frontend-complete-20261104.3';
import {mountAssetLifecycle} from './asset-lifecycle.mjs?v=frontend-complete-20261104.3';
const server=demo?null:new ServerResources(true);
if(server){await requireSession(['resources.manage','requests.review','inventory.manage','logs.review']);markConnected();}
const actionPermission={ 'room-new':'resources.manage','room-edit':'resources.manage','room-delete':'resources.manage','asset-delete':'resources.manage','asset-new':'resources.manage','asset-edit':'resources.manage','stock-new':'resources.manage','maintenance-new':'resources.manage','maintenance-open':'resources.manage','inventory-new':'inventory.manage','inventory-open':'inventory.manage','log-open':'logs.review'};
const operationPermission={'room-delete':'resources.manage','asset-delete':'resources.manage',room:'resources.manage','server-asset':'resources.manage','server-stock':'resources.manage',review:'requests.review',handover:'resources.manage',return:'resources.manage','receipt-resolve':'resources.manage',log:'logs.review','inventory-create':'inventory.manage','inventory-save':'inventory.manage','maintenance-plan':'resources.manage','maintenance-start':'resources.manage','maintenance-finish':'resources.manage','maintenance-cancel':'resources.manage'};
function allowedAction(action,id=''){if(!server)return true;const permission=actionPermission[action];if(!permission)return true;if(!can(permission))return false;if(['room-new','asset-new','inventory-new'].includes(action)&&!departmentsFor(permission,server.departments).some(d=>d.active))return false;const row=db?.assets.find(r=>r.id===id)||db?.catalog.rooms.find(r=>r.id===id)||db?.inventories.find(r=>r.id===id);return !row||resourceAllows(identity,permission,row.api?.departmentId||row.departmentId,row.api?.ownerId);}

function installServerResources(){
 labels.receipt_disputed='Sai lệch khi nhận';
 let busy=false;
 async function task(button,work){if(busy)return;busy=true;if(button)button.disabled=true;try{await work();db=await server.load();if(route==='calendar')await server.availability(filters.calendar.date);$('#dialog').close();render();toast('Đã lưu dữ liệu trên máy chủ.');}catch(e){if(e.status===401)location.assign('login.html');const box=$('#form-error');if(box)box.textContent=e.message;else toast(e.message);}finally{busy=false;if(button)button.disabled=false;}}
 function assetFormServer(id,stock=false){
  const a=db.assets.find(a=>a.id===id);const departments=departmentsFor('resources.manage',server.departments).filter(d=>d.active);
  const body=stock?field('quantity','Số lượng nhập thêm',input('quantity','number','1','required min="1" max="1000000"')):
   field('code','Mã tài sản',input('code','text',a?.api.code||'','required maxlength="30"'))+field('name','Tên tài sản',input('name','text',a?.name||'','required maxlength="150"'))+field('category','Nhóm',input('category','text',a?.api.category||'','required maxlength="100"'))+field('unit','Đơn vị tính',input('unit','text',a?.api.unit||'chiếc','required maxlength="30"'))+field('departmentId','Đơn vị quản lý',select('departmentId',departments.map(d=>[d.id,d.name]),a?.api.departmentId||identity.departmentId))+field('active','Trạng thái hoạt động',select('active',[['true','Đang hoạt động'],['false','Ngừng hoạt động']],String(a?.api.active??true)));
  const quantity=stock?'':a?field('quantity','Số lượng theo sổ',input('quantity','number',a.quantity,'required min="0" max="1000000" step="1"')):field('quantity','Số lượng ban đầu *',input('quantity','number','1','required min="1" max="1000000" step="1"'));
  modal(stock?'Nhập kho thiết bị':a?'Cập nhật hồ sơ tài sản':'Thêm nhóm tài sản',form(stock?'server-stock':'server-asset',id,`<div class="form-grid">${body}${quantity}</div><p class="form-note">Có thể sửa số lượng trực tiếp; mọi thay đổi được ghi lịch sử. Không thể giảm thấp hơn số đang mượn, hỏng, mất hoặc đã giữ cho lịch sử dụng.</p>`));
 }
 document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b)return;
  if(b.dataset.action==='resource-page'){e.preventDefault();e.stopImmediatePropagation();loadResourceRoute(Number(b.dataset.id));return;}
  if(!allowedAction(b.dataset.action,b.dataset.id)){e.preventDefault();e.stopImmediatePropagation();toast('Bạn không có quyền thực hiện thao tác này trong phạm vi hồ sơ.');return;}
  if(['room-delete','asset-delete'].includes(b.dataset.action)){
   e.preventDefault();e.stopImmediatePropagation();
   const room=b.dataset.action==='room-delete',row=(room?db.catalog.rooms:db.assets).find(r=>r.id===b.dataset.id);
   if(!row)return;
   modal('Xóa '+(room?'phòng':'tài sản'),form(b.dataset.action,row.id,`<p>Bạn muốn xóa <strong>${esc(row.name)}</strong> khỏi danh mục đang sử dụng?</p><p class="form-note">Hệ thống sẽ ngừng hoạt động hồ sơ và giữ lại lịch sử. Có thể khôi phục bằng Cập nhật trong bộ lọc Ngừng hoạt động / Ngừng phục vụ.</p>`,'Xác nhận xóa'));return;
  }
  if(b.dataset.action==='inventory-open'){e.preventDefault();e.stopImmediatePropagation();server.inventoryDetail(b.dataset.id).then(()=>{db=server.snapshot;inventoryOpen(b.dataset.id);}).catch(err=>toast(err.message));return;}
  if(b.dataset.action==='maintenance-new'){e.preventDefault();e.stopImmediatePropagation();openMaintenancePicker(b.dataset.id).catch(err=>toast(err.message));return;}
  if(['asset-new','asset-edit','stock-new'].includes(b.dataset.action)){e.preventDefault();e.stopImmediatePropagation();assetFormServer(b.dataset.id,b.dataset.action==='stock-new');}
  if(b.dataset.action==='help'){e.preventDefault();e.stopImmediatePropagation();toast('Bảo trì có chi phí tạo yêu cầu thanh toán. Kế toán ghi chứng từ sau khi kiểm tra ngân sách. Dùng Tải lại dữ liệu để nhận trạng thái mới.');}
  if(['export','print','reminder'].includes(b.dataset.action)){e.preventDefault();e.stopImmediatePropagation();toast('Chức năng này chưa có API và chưa được bật trong phiên dữ liệu thật.');}
 },true);
 document.addEventListener('submit',e=>{
  const f=e.target;if(!f.dataset.operation)return;e.preventDefault();e.stopImmediatePropagation();
  const values=new FormData(f),p=Object.fromEntries(values),op=e.submitter?.name==='printCost'?'maintenance-cost':f.dataset.operation,id=f.dataset.id||p.id;p.id=id;
  if(op==='inventory-save'){p.rows=db.inventories.find(i=>i.id===id).rows.map((r,i)=>({id:r.id,actual:p['actual-'+i],condition:p['condition-'+i],notes:p['notes-'+i]}));p.finish=e.submitter?.name==='finish';}
  if(operationPermission[op]&&!can(operationPermission[op])){toast('Bạn không có quyền thực hiện thao tác này.');return;}
  task(e.submitter,async()=>{
   if(op==='server-stock'){const a=db.assets.find(a=>a.id===id);return keyed(`/equipment/${id}/stock`,{version:a.api.version,quantity:Number(p.quantity),note:null});}
   if(op==='server-asset'){const a=db.assets.find(a=>a.id===id);const data={...assetPayload(p,a?.api),quantity:Number(p.quantity)};return a?await api.request(`/equipment/${id}`,{method:'PUT',data}):await keyed('/equipment',data);}
   return server.manage(op,p);
  });
 },true);
 document.addEventListener('change',e=>{if(e.target.name!=='date'||!e.target.closest('#filters'))return;e.stopImmediatePropagation();const date=e.target.value;filters.calendar.date=date;loadResourceRoute(1);},true);
 const observer=new MutationObserver(()=>{
  if(!$('#dialog').open)return;
  const date=$('[data-operation=inventory-create] [name=date]');if(date){date.readOnly=true;date.value=TODAY;}
  const room=$('[data-operation=room] [name=building]');if(room)room.disabled=true;
  const tags=$('[data-operation=room] [name=tags]');if(tags)tags.disabled=true;
  const print=$('[name=printCost]');if(print){print.disabled=true;print.title='Kế toán ghi chứng từ khi thanh toán; chưa có phiếu chi ở bước ghi chi phí.';}
  $('#dialog-body').querySelectorAll('a[href^="payment-voucher.html"]').forEach(a=>a.hidden=true);
  $('#dialog-body').querySelectorAll('.form-note').forEach(p=>{if(p.textContent.includes('Chi phí được chuyển vào yêu cầu chi'))p.textContent='Chi phí dương chuyển vào hàng chờ kế toán trong cùng giao dịch hoàn tất. Chưa trừ ngân sách cho đến khi kế toán ghi chi.';});
  const dialog=$('#dialog-body');const id=dialog.querySelector('[data-operation]')?.dataset.id;
  if(can('resources.manage')&&!dialog.querySelector('[data-action=stock-new]')&&$('#dialog-title').textContent==='Hồ sơ tài sản'){const assetId=db.assets.find(a=>dialog.textContent.includes(a.id))?.id;if(assetId)dialog.insertAdjacentHTML('beforeend',btn('Nhập kho bổ sung','stock-new',assetId,true));}
  const disputed=db.requests.find(r=>r.status==='receipt_disputed'&&dialog.textContent.includes(r.id));
  if(disputed&&resourceAllows(identity,'resources.manage',disputed.manageDepartmentId||disputed.api.departmentId,disputed.api.ownerId)&&!dialog.querySelector('[data-operation=receipt-resolve]'))dialog.insertAdjacentHTML('beforeend',form('receipt-resolve',disputed.id,field('notes','Kết quả xử lý sai lệch',area('notes')),'Mời người mượn xác nhận lại'));
 });observer.observe($('#dialog-body'),{childList:true});
}
import {RESOURCE_KEY,readResources,manageResources,roomReservations,deviceFree,overdue} from './resource-store.mjs';
import {TODAY} from './resource-seed.mjs';
import {freeIntervals} from './availability.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',building:'M3 21h18 M5 21V8h14v13 M3 8l9-5 9 5z M9 11v5 M15 11v5 M10 21v-3h4v3',room:'M4 21V5l11-2v18 M15 7h5v14 M2 21h20 M11 12h.01',equipment:'M3 4h18v12H3z M8 21h8 M12 16v5 M6 8h5 M6 11h8',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4 M8 14h2 M14 14h2',file:'M14 3H5v18h14V8z M14 3v5h5 M8 12h8 M8 16h5',inventory:'M9 4h6v3H9z M9 5H5v16h14V5h-4 M8 12h8 M8 16h8',tool:'M21 3l-6 6-3-3 6-6 M14 2a6 6 0 0 0-6 8L2 16v5h5l6-6a6 6 0 0 0 8-7',book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1z M12 5v15',chart:'M4 3v18h18 M8 16v-5 M13 16V6 M18 16V9',menu:'M3 6h18 M3 12h18 M3 18h18',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',chevron:'M8 10l4 4 4-4',arrow:'M4 12h16 M15 7l5 5-5 5',close:'M6 6l12 12 M6 18L18 6',plus:'M12 5v14 M5 12h14',check:'M20 6L9 17l-5-5',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 6v6l4 2',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v7H6z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const fmtDate=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('vi-VN'):'—';
const stamp=d=>d?new Date(d).toLocaleString('vi-VN',{dateStyle:'short',timeStyle:'short'}):'—';
const money=n=>n==null?'Chưa kê khai':new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(n)+' đ';
const labels={pending:'Chờ xét duyệt',approved:'Đã duyệt',rejected:'Từ chối',cancelled:'Đã hủy',draft:'Bản nháp',ready:'Chờ người mượn xác nhận',borrowed:'Đang mượn',return_pending:'Chờ tiếp nhận trả',completed:'Hoàn tất',confirmed:'Đã xác nhận',needs_update:'Cần bổ sung',planned:'Đã lên kế hoạch',running:'Đang bảo trì',open:'Đang kiểm kê',issue:'Chờ xử lý',overdue:'Quá hạn trả'};
const actionLabels={review:'Xét duyệt đăng ký',handover:'Ghi nhận bàn giao',return:'Tiếp nhận trả thiết bị',log:'Xác nhận nhật ký',room:'Cập nhật phòng',asset:'Cập nhật tài sản','inventory-create':'Lập đợt kiểm kê','inventory-save':'Ghi nhận kiểm kê','maintenance-plan':'Lập kế hoạch bảo trì','maintenance-start':'Bắt đầu bảo trì','maintenance-finish':'Hoàn tất bảo trì',reminder:'Ghi nhắc việc nội bộ'};
const badge=(s,text)=>`<span class="badge ${esc(s)}">${esc(text||labels[s]||s)}</span>`;
const menus=[...(server?[["lifecycle","building","Nguy\u00ean gi\u00e1 v\u00e0 thanh l\u00fd"]]:[]),['overview','grid','Tổng quan'],['rooms','room','Danh mục phòng'],['calendar','calendar','Lịch sử dụng phòng'],['approvals','file','Duyệt đăng ký'],['loans','equipment','Mượn / trả thiết bị'],['assets','building','Hồ sơ tài sản'],['inventory','inventory','Kiểm kê tài sản'],['maintenance','tool','Bảo trì & sửa chữa'],['logs','book','Xác nhận nhật ký'],['reports','chart','Báo cáo quản trị']].filter(([id])=>!server||({overview:true,lifecycle:can('resources.manage'),rooms:can('resources.manage')||can('requests.review'),calendar:can('resources.manage')||can('requests.review'),approvals:can('requests.review'),loans:can('resources.manage')||can('requests.review'),assets:can('resources.manage'),inventory:can('inventory.manage'),maintenance:can('resources.manage'),logs:can('logs.review'),reports:can('reports.read')||can('reports.export')})[id]);
let db,storageIssue='',route='overview',toastTimer;
if(server)db=null;else try{db=readResources();if(localStorage.getItem(RESOURCE_KEY)===null)localStorage.setItem(RESOURCE_KEY,JSON.stringify(db));}catch(e){storageIssue=e.message||'Không truy cập được bộ nhớ trình duyệt.';db=readResources({getItem:()=>null});}
const filters={rooms:{search:'',building:'',status:''},calendar:{date:TODAY,room:''},approvals:{search:'',kind:'',status:''},loans:{search:'',status:'',from:'',to:''},assets:{search:'',unit:'',status:''},inventory:{search:'',status:''},maintenance:{search:'',status:''},logs:{search:'',status:''},reports:{type:'catalog',from:'',to:'',unit:''}};
if(server){route=location.hash.replace(/^#\//,'')||'overview';if(!menus.some(m=>m[0]===route))route='overview';db=await server.loadPage(route,filters[route]||{},1);}
function latest(){if(server)return db;if(!storageIssue)try{db=readResources();}catch(e){storageIssue=e.message;}return db;}
let resourceLoadRevision=0,resourceFilterTimer;
async function loadResourceRoute(page=1){
 const revision=++resourceLoadRevision;let next=location.hash.replace(/^#\//,'')||'overview';if(!menus.some(m=>m[0]===next))next='overview';
 $('#main').inert=true;try{let result=await server.loadPage(next,filters[next]||{},page);if(revision!==resourceLoadRevision)return;
  if(server.pageInfo?.total>0&&page>Math.ceil(server.pageInfo.total/20))result=await server.loadPage(next,filters[next]||{},Math.ceil(server.pageInfo.total/20));
  if(revision!==resourceLoadRevision)return;db=result;route=next;if(route==='calendar')await server.availability(filters.calendar.date);if(revision!==resourceLoadRevision)return;render();
 }catch(e){if(revision===resourceLoadRevision)toast('Không tải được dữ liệu: '+e.message);}finally{if(revision===resourceLoadRevision)$('#main').inert=false;}
}
function serverOverview(){
 const s=db.summary;if(!s)return heading('Tổng quan nguồn lực','Đang tải số liệu tổng hợp theo phạm vi tài khoản.');
 const cards=[['Phòng trong phạm vi',s.roomCount,'phòng','rooms','room'],['Nhóm tài sản',s.assetCount,'nhóm','assets','equipment'],['Số lượng theo sổ',s.owned,'đơn vị','assets','building'],['Đăng ký chờ duyệt',s.pending,'phiếu','approvals','file'],['Yêu cầu trả chờ tiếp nhận',s.returns,'phiếu','loans','equipment'],['Đợt kiểm kê đang mở',s.openInventory,'đợt','inventory','inventory'],['Bảo trì đang chạy',s.runningMaintenance,'kế hoạch','maintenance','tool'],['Nhật ký chờ xác nhận',s.pendingLogs,'nhật ký','logs','book']].filter(([,value])=>value!=null);
 return heading('Tổng quan nguồn lực','Số tổng hợp SQL trên toàn bộ hồ sơ trong phạm vi từng quyền; không cộng từ trang đang xem.')+`<section class="stats">${cards.map(([label,value,unit,url,i])=>`<a href="#/${url}" style="color:inherit;text-decoration:none">${stat(label,value,unit,'Theo phạm vi tài khoản',i)}</a>`).join('')}</section><p class="subline">Cập nhật lúc ${stamp(s.generatedAt)}. Chọn một chức năng để tải danh sách 20 hồ sơ mỗi trang.</p>`;
}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function menu(open){$('#sidebar').classList.toggle('open',open);$('#backdrop').classList.toggle('show',open);$('[data-action=menu]').setAttribute('aria-expanded',String(open));}
function heading(title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">QUẢN LÝ PHÒNG & TÀI SẢN · THEO PHẠM VI TÀI KHOẢN</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions||`<div class="date-pill">${icon('calendar')}${fmtDate(TODAY)}</div>`}</div></div>`;}
const btn=(label,act,id='',primary=false)=>allowedAction(act,id)?`<button class="btn ${primary?'primary':''}" data-action="${act}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`:'';
function empty(text='Không có dữ liệu phù hợp',desc='Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm.'){return `<div class="empty">${icon('file')}<h3>${text}</h3><p>${desc}</p></div>`;}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();}
function stat(label,value,unit,foot,i){return `<article class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${value}<span>${unit}</span></div><div class="stat-foot">${foot}</div></article>`;}
function requestRows(rows){return table(['PHIẾU / NGƯỜI ĐĂNG KÝ','THỜI GIAN','SỐ LƯỢNG','TRẠNG THÁI',''],rows.map(r=>[`<strong>${esc(r.name)}</strong><small class="record-code">${esc(r.id)} · ${r.ownerName?esc(r.ownerName):'Nguyễn Minh Anh'}</small>`,`${fmtDate(r.date)}<small class="record-code">${esc(r.start)} – ${esc(r.end)}</small>`,r.kind==='room'?`${r.students} người`:`${r.quantity} thiết bị${r.returned?`<small class="record-code">Đã xử lý trả: ${r.returned}</small>`:''}`,badge(r.status)+(overdue(r)?`<small class="record-code">${badge('overdue')}</small>`:''),`<div class="actions-cell">${btn('Xem phiếu','request',r.id)}</div>`]));}
function overview(){const pending=db.requests.filter(r=>r.status==='pending'),returns=db.requests.filter(r=>r.status==='return_pending'),late=db.requests.filter(r=>overdue(r)),running=db.maintenance.filter(m=>m.status==='running'),roomCount=db.catalog.rooms.length,units=db.assets.reduce((s,a)=>s+a.quantity,0),logs=db.logs.filter(l=>l.status==='pending');return heading('Tổng quan nguồn lực','Một không gian thống nhất để quản lý phòng, tài sản và thiết bị.')+`<section class="hero"><div class="hero-copy"><div class="hero-tag"><span class="tiny-dot"></span>SẴN SÀNG CHO MỖI GIỜ HỌC</div><h2>Quản lý tập trung. Vận hành thông suốt.</h2><p>Có ${pending.length} đăng ký cần xét duyệt và ${returns.length} yêu cầu trả chờ tiếp nhận.<br>Theo dõi lịch phòng, kiểm soát bàn giao và cập nhật tình trạng tài sản.</p><div class="hero-actions"><a class="btn primary" href="#/approvals">${icon('file')}Duyệt đăng ký ${icon('arrow')}</a><a class="btn ghost" href="#/calendar">Xem lịch phòng</a></div></div><div class="hero-stamp">${icon('building')}</div></section><section class="stats">${stat('Phòng trong danh mục',roomCount,'phòng',`${db.catalog.rooms.filter(r=>r.available).length} phòng đang phục vụ`,'room')}${stat('Hồ sơ tài sản',db.assets.length,'hồ sơ',`${units} đơn vị tài sản theo sổ`,'equipment')}${stat('Đăng ký chờ duyệt',pending.length,'phiếu','Phòng học và thiết bị','file')}${stat('Quá hạn trả thiết bị',late.length,'phiếu','Còn thiết bị chưa tiếp nhận trả','clock')}</section><div class="content-grid"><div><section class="panel"><div class="panel-head"><div><h2>Đăng ký cần xử lý</h2><p>Các phiếu từ không gian giảng viên</p></div><a class="text-link" href="#/approvals">Tất cả ${icon('arrow')}</a></div>${requestRows(pending.slice(0,4))}</section><section class="panel"><div class="panel-head"><h2>Lịch phòng hôm nay</h2><a class="text-link" href="#/calendar">Xem lịch ${icon('arrow')}</a></div>${todaySchedule()}</section></div><div class="exec-side"><section class="panel"><div class="panel-head"><h2>Việc cần theo dõi</h2></div>${[['loans','Yêu cầu trả chờ tiếp nhận',returns.length],['logs','Nhật ký chờ xác nhận',logs.length],['maintenance','Kế hoạch đang thực hiện',running.length],['inventory','Đợt kiểm kê đang mở',db.inventories.filter(i=>i.status==='open').length]].map(([url,label,n])=>`<a class="notice-link" href="#/${url}">${icon(url==='maintenance'?'tool':'file')}<span>${label}</span><b>${n}</b>${icon('arrow')}</a>`).join('')}<div class="compact-note">Dữ liệu được dùng chung qua máy chủ với giảng viên. Dùng Tải lại dữ liệu để cập nhật. Bàn giao và trả thiết bị là hai bước xác nhận riêng.</div></section><section class="panel"><div class="panel-head"><h2>Hoạt động gần đây</h2></div><div class="activity">${db.resourceAudit.length?db.resourceAudit.slice(-5).reverse().map(a=>`<div class="activity-item"><span class="activity-dot">${icon('check')}</span><div><h3>${esc(actionLabels[a.action]||a.action)}</h3><p>${esc(a.target)} · ${stamp(a.at)}</p></div></div>`).join(''):empty('Chưa có thao tác quản lý','Các cập nhật sẽ xuất hiện tại đây.')}</div></section></div></div>`;}
function todaySchedule(){const rows=[...db.requests,...db.roomReservations].filter(r=>r.kind==='room'&&r.date===TODAY&&r.status==='approved').sort((a,b)=>a.start.localeCompare(b.start));return rows.length?`<div class="calendar-list">${rows.slice(0,4).map(r=>`<div class="booking-row"><div class="time">${r.start}–${r.end}</div><div><h3>${esc(r.name||db.catalog.rooms.find(x=>x.id===r.resource)?.name||r.resource)}</h3><p>${esc(r.purpose||'Lịch của giảng viên khác · Dữ liệu mẫu')}</p></div>${badge('approved')}</div>`).join('')}</div>`:empty('Không có lịch đã duyệt hôm nay');}
const option=(v,l,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`;
const field=(name,label,input,full=false)=>`<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label>${input}</div>`;
const input=(name,type='text',value='',attrs='')=>`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;
const select=(name,choices,value='')=>`<select id="f-${name}" name="${name}">${choices.map(c=>option(...c,value)).join('')}</select>`;
const area=(name,value='',attrs='')=>`<textarea id="f-${name}" name="${name}" maxlength="1000" ${attrs}>${esc(value)}</textarea>`;
function toolbar(body){return `<form class="list-toolbar" id="filters" role="search">${body}</form>`;}
function searchField(value){return `<div class="field search"><label for="filter-search">Tìm kiếm</label><input id="filter-search" name="search" type="search" value="${esc(value)}" placeholder="Nhập tên hoặc mã…"></div>`;}
function filterSelect(name,label,choices,value){return field(name,label,select(name,choices,value));}
function rooms(){const f=filters.rooms,rows=db.catalog.rooms.filter(r=>(!f.building||r.building===f.building)&&(!f.status||String(r.available)===f.status)&&matches(r,f.search));return heading('Danh mục phòng','Cập nhật thông tin, sức chứa và tình trạng phục vụ của phòng.',btn(icon('plus')+'Đăng ký phòng','room-new','',true))+toolbar(searchField(f.search)+filterSelect('building',server?'Đơn vị sở hữu':'Tòa nhà',[['',server?'Tất cả đơn vị':'Tất cả tòa nhà'],...(server?server.departments.map(d=>[d.name,d.name]):[...new Set(db.catalog.rooms.map(r=>r.building))].map(b=>[b,b]))],f.building)+filterSelect('status','Tình trạng',[['','Tất cả'],['true','Đang phục vụ'],['false','Ngừng phục vụ']],f.status))+`<div id="results"><p class="subline">${rows.length} ${server?'trên trang · ':''}phòng phù hợp · Giờ phục vụ 07:00–18:00</p><div class="grid-cards">${rows.map(r=>`<article class="room-card"><div class="room-head">${icon('room')}${badge(r.available?'approved':'issue',r.available?'Đang phục vụ':'Ngừng phục vụ')}</div><div class="room-body"><h2>${esc(r.name)}</h2><p>${esc(r.building)} · ${esc(r.type)} · ${r.seats} chỗ<span class="catalog-id">${esc(r.api?.code||r.id)}</span></p><div class="tags">${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="room-actions">${btn('Cập nhật','room-edit',r.id)}${server&&r.available?btn('Xóa','room-delete',r.id):''}<button class="btn" data-action="room-calendar" data-id="${esc(r.id)}">Xem lịch ${icon('arrow')}</button></div></div></article>`).join('')||empty()}</div></div>`;}
function calendar(){const f=filters.calendar,rooms=db.catalog.rooms.filter(r=>!f.room||r.id===f.room);return heading('Lịch sử dụng phòng','Đối chiếu lượt đã duyệt, giữ chỗ chờ duyệt và khoảng giờ bảo trì.')+toolbar(field('date','Ngày xem lịch',input('date','date',f.date,'required'))+filterSelect('room','Phòng',[['','Tất cả phòng'],...db.catalog.rooms.map(r=>[r.id,r.name])],f.room))+rooms.map(r=>{const busy=roomReservations(db,r.id,f.date).sort((a,b)=>a.start.localeCompare(b.start)),free=r.available?freeIntervals(busy):[];return `<section class="panel"><div class="panel-head"><div><h2>${esc(r.name)}</h2><p>${r.seats} chỗ · ${esc(r.type)} · ${fmtDate(f.date)}</p></div>${badge(r.available?'approved':'issue',r.available?'Đang phục vụ':'Ngừng phục vụ')}</div><div class="calendar-list">${busy.map(b=>`<div class="booking-row"><div class="time">${b.start}–${b.end}<small>${b.maintenance?'Bảo trì':'Giữ chỗ'}</small></div><div><h3>${esc(b.purpose||(b.maintenance?'Lịch bảo trì':'Lịch giảng viên khác'))}</h3><p>${esc(b.id)}</p></div>${badge(b.status)}${db.requests.some(x=>x.id===b.id)?btn('Chi tiết','request',b.id):''}</div>`).join('')||'<p class="subline">Chưa có lượt giữ chỗ trong ngày.</p>'}<div class="free-slots-display">${free.length?'<span>Khoảng còn trống:</span>'+free.map(s=>`<span>${s.start}–${s.end}</span>`).join(''):`<span>${r.available?'Không còn khoảng trống':'Phòng tạm ngừng phục vụ'}</span>`}</div></div></section>`;}).join('');}
function matches(r,q){if(server)return true;return Object.values(r).filter(v=>typeof v==='string').join(' ').toLocaleLowerCase('vi').includes(String(q||'').trim().toLocaleLowerCase('vi'));}
function approvals(){const f=filters.approvals,rows=db.requests.filter(r=>r.status!=='draft'&&(!f.kind||r.kind===f.kind)&&(!f.status||r.status===f.status)&&matches(r,f.search));return heading('Duyệt đăng ký','Kiểm tra lịch phòng và thiết bị khả dụng trước khi xét duyệt.')+toolbar(searchField(f.search)+filterSelect('kind','Loại đăng ký',[['','Tất cả'],['room','Sử dụng phòng'],['device','Mượn thiết bị']],f.kind)+filterSelect('status','Trạng thái',[['pending','Chờ xét duyệt'],['approved','Đã duyệt'],['rejected','Từ chối'],['','Tất cả trạng thái']],f.status))+`<div id="results"><p class="subline">${rows.length} ${server?'trên trang · ':''}phiếu phù hợp · Bản nháp của giảng viên chưa được gửi để xử lý.</p><section class="panel">${requestRows(rows)}</section></div>`;}
function loans(){const f=filters.loans,rows=db.requests.filter(r=>r.kind==='device'&&r.status!=='draft'&&(!f.status||(f.status==='overdue'?overdue(r):r.status===f.status))&&(!f.from||r.date>=f.from)&&(!f.to||r.date<=f.to)&&matches(r,f.search));return heading('Mượn / trả thiết bị','Bàn giao, tiếp nhận trả từng phần và theo dõi các phiếu quá hạn.')+`<div class="mini-stats"><div class="mini-stat">Chờ bàn giao<b>${db.requests.filter(r=>r.kind==='device'&&r.status==='approved').length}</b></div><div class="mini-stat">Chờ tiếp nhận trả<b>${db.requests.filter(r=>r.status==='return_pending').length}</b></div><div class="mini-stat">Quá hạn còn phải trả<b>${db.requests.filter(r=>overdue(r)).length}</b></div></div>`+toolbar(searchField(f.search)+filterSelect('status','Trạng thái',[['','Tất cả'],['approved','Chờ bàn giao'],['ready','Chờ người mượn xác nhận'],['borrowed','Đang mượn'],['return_pending','Chờ tiếp nhận trả'],['overdue','Quá hạn trả'],['completed','Hoàn tất']],f.status)+field('from','Ngày mượn từ',input('from','date',f.from))+field('to','Đến ngày',input('to','date',f.to)))+`<div id="results"><p class="subline">${rows.length} ${server?'trên trang · ':''}phiếu phù hợp · Số đang giữ chỉ giảm sau khi cán bộ tiếp nhận trả.</p><section class="panel">${requestRows(rows)}</section></div>`;}
function assets(){const f=filters.assets,rows=db.assets.filter(a=>(!f.unit||a.unit===f.unit)&&(!f.status||(f.status==='active'?a.api?.active!==false:f.status==='inactive'?a.api?.active===false:f.status==='issue'?a.unusable+a.lost>0:a.unusable+a.lost===0))&&matches(a,f.search));return heading('Hồ sơ tài sản','Quản lý thông tin tài sản và các nhóm thiết bị cho mượn.',btn(icon('plus')+'Đăng ký tài sản','asset-new','',true))+toolbar(searchField(f.search)+filterSelect('unit','Đơn vị quản lý',[['','Tất cả đơn vị'],...(server?server.departments.map(d=>[d.name,d.name]):[...new Set(db.assets.map(a=>a.unit))].map(u=>[u,u]))],f.unit)+filterSelect('status','Tình trạng',[['','Tất cả'],['good','Không có bất thường'],['issue','Có hỏng / mất'],...(server?[['active','Đang hoạt động'],['inactive','Ngừng hoạt động']]:[])],f.status))+`<div id="results"><p class="subline">${rows.length} ${server?'trên trang · ':''}hồ sơ · Thiết bị được quản lý theo nhóm cùng loại, chưa định danh serial từng chiếc.</p><section class="panel">${table(['TÀI SẢN / MÃ','ĐƠN VỊ / VỊ TRÍ','SỐ LƯỢNG','TÌNH TRẠNG',''],rows.map(a=>[`<strong>${esc(a.name)}</strong><small class="record-code">${esc(a.api?.code||a.id)}</small>`,`${esc(a.unit)}<small class="record-code">${esc(a.location)}</small>`,`${a.quantity}<small class="record-code">Hỏng ${a.unusable} · Mất ${a.lost}</small>`,(server&&a.api.active===false?badge('cancelled','Ngừng hoạt động'):'')+badge(a.unusable+a.lost?'issue':'approved',a.unusable+a.lost?'Có bất thường':'Không có bất thường'),`<div class="actions-cell">${btn('Hồ sơ','asset-view',a.id)}${server?btn('Cập nhật','asset-edit',a.id):''}${server&&a.api.active?btn('Xóa','asset-delete',a.id):''}</div>`]))}<div class="data-note">Số lượng theo sổ gồm tài sản đang giữ/mượn, hỏng và mất đã ghi nhận. Phần hỏng/mất không được tính là thiết bị tốt để cho mượn.</div></section></div>`;}
function inventory(){const f=filters.inventory,rows=db.inventories.filter(i=>(!f.status||i.status===f.status)&&matches(i,f.search));return heading('Kiểm kê tài sản','Lập đợt, đối chiếu số thực tế và ghi nhận chênh lệch.',btn(icon('plus')+'Lập đợt kiểm kê','inventory-new','',true))+toolbar(searchField(f.search)+filterSelect('status','Trạng thái',[['','Tất cả'],['open','Đang kiểm kê'],['completed','Hoàn tất']],f.status))+`<div id="results"><section class="panel">${rows.length?table(['ĐỢT KIỂM KÊ','PHẠM VI / NGÀY','TIẾN ĐỘ','TRẠNG THÁI',''],rows.map(i=>[`<strong>${esc(i.name)}</strong><small class="record-code">${esc(i.id)}</small>`,`${esc(i.unit)}<small class="record-code">${fmtDate(i.date)}</small>`,`${i.counted??i.rows.filter(r=>r.actual!==null&&r.condition).length}/${i.itemCount??i.rows.length} hồ sơ`,badge(i.status),`<div class="actions-cell">${btn('Mở đợt','inventory-open',i.id)}</div>`])):empty('Chưa có đợt kiểm kê','Lập đợt để lưu danh sách và số lượng theo sổ tại thời điểm bắt đầu.')}<div class="data-note">Kết quả kiểm kê là bản đối chiếu. Hoàn tất đợt không tự điều chỉnh kho hoặc xóa tài sản có chênh lệch.</div></section></div>`;}
function maintenance(){const f=filters.maintenance,rows=db.maintenance.filter(m=>(!f.status||m.status===f.status)&&matches(m,f.search));return heading('Bảo trì & sửa chữa','Lập lịch, theo dõi thực hiện và ghi nhận kết quả bảo trì.',btn(icon('plus')+'Lập kế hoạch','maintenance-new','',true))+toolbar(searchField(f.search)+filterSelect('status','Trạng thái',[['','Tất cả'],['planned','Đã lên kế hoạch'],['running','Đang thực hiện'],['completed','Hoàn tất']],f.status))+`<div id="results"><section class="panel">${rows.length?rows.map(m=>`<article class="maintenance-card"><span>${icon('tool')}</span><div class="maintenance-info">${badge(m.status)}<h3>${esc(m.name)}</h3><p>${esc(m.id)} · ${m.quantity} đơn vị · ${m.mode==='repair'?'Sửa chữa tài sản hỏng':'Bảo trì thiết bị đang tốt'}</p><p>${stamp(m.start)} → ${stamp(m.end)}</p><p class="break">${esc(m.content)}</p>${m.status==='completed'?`<p>Chi phí: ${money(m.cost)} · ${m.result==='good'?'Hoạt động tốt':'Chưa khả dụng'}</p>`:''}${btn('Chi tiết / xử lý','maintenance-open',m.id)}</div></article>`).join(''):empty('Chưa có kế hoạch bảo trì','Chọn tài sản để lập lịch; thời gian bảo trì sẽ được phản ánh vào khả dụng.')}<div class="data-note">Chi phí dương chuyển vào hàng chờ thanh toán; chứng từ xuất hiện sau khi kế toán ghi chi. Không tự tạo thêm khoản chi hoặc thay đổi ngân sách Ban Giám hiệu.</div></section></div>`;}
function logs(){const f=filters.logs,rows=db.logs.filter(l=>(!f.status||l.status===f.status)&&matches({...l,name:db.requests.find(r=>r.id===l.request)?.name},f.search));return heading('Xác nhận nhật ký','Đối chiếu lịch đăng ký và thời gian, tình trạng sử dụng thực tế.')+toolbar(searchField(f.search)+filterSelect('status','Trạng thái',[['pending','Chờ xác nhận'],['needs_update','Cần bổ sung'],['confirmed','Đã xác nhận'],['','Tất cả']],f.status))+`<div id="results"><section class="panel">${table(['NHẬT KÝ / NGUỒN LỰC','THỜI GIAN THỰC TẾ','TÌNH TRẠNG','TRẠNG THÁI',''],rows.map(l=>[`<strong>${esc(db.requests.find(r=>r.id===l.request)?.name||l.request)}</strong><small class="record-code">${esc(l.id)}</small>`,`${fmtDate(l.date)}<small class="record-code">${esc(l.start)}–${esc(l.end)}</small>`,esc(l.condition),badge(l.status),`<div class="actions-cell">${btn('Đối chiếu','log-open',l.id)}</div>`]))}</section></div>`;}
function reportData(){const f=filters.reports,within=d=>(!f.from||d>=f.from)&&(!f.to||d<=f.to);if(f.type==='loans'){const rows=db.requests.filter(r=>r.kind==='device'&&!['draft','cancelled','rejected','pending'].includes(r.status)&&within(r.date));return {title:'Báo cáo mượn và trả thiết bị',headers:['Mã phiếu','Thiết bị','Ngày mượn','Số mượn','Đã xử lý trả','Còn giữ','Trạng thái','Quá hạn'],rows:rows.map(r=>[r.id,r.name,r.date,r.quantity,r.returned||0,r.quantity-(r.returned||0),labels[r.status],overdue(r)?'Có':'Không']),note:'Đã xử lý trả gồm thiết bị tốt, hỏng và mất đã được cán bộ xác nhận. Quá hạn được đối chiếu tại thời điểm xem báo cáo.'};}if(f.type==='maintenance'){const rows=db.maintenance.filter(m=>m.status==='completed'&&within(localTime(m.finishedAt).slice(0,10)));return {title:'Báo cáo chi phí bảo trì đã ghi nhận',headers:['Mã kế hoạch','Tài sản','Ngày hoàn tất','Chi phí (đồng)','Chứng từ tham chiếu','Kết quả'],rows:rows.map(m=>[m.id,m.name,localTime(m.finishedAt).slice(0,10),m.cost,m.voucher||'Không phát sinh',m.result==='good'?'Tốt':'Chưa khả dụng']),note:'Chi phí liên kết chứng từ mẫu. Không cộng thêm một lần nữa vào chi thực hiện của kế toán.'};}const rows=db.assets.filter(a=>!f.unit||a.unit===f.unit);return {title:'Báo cáo danh mục và tình trạng tài sản',headers:['Mã tài sản','Tên tài sản','Đơn vị','Số lượng theo sổ','Hỏng / chờ xử lý','Mất','Nguyên giá đơn vị (đồng)'],rows:rows.map(a=>[a.id,a.name,a.unit,a.quantity,a.unusable,a.lost,a.price]),note:'Ảnh chụp số liệu hiện tại theo nhóm tài sản. Bộ lọc thời gian áp dụng cho báo cáo mượn/trả và bảo trì.'};}
function reports(){const f=filters.reports,r=reportData();return heading('Báo cáo quản trị','Tổng hợp dữ liệu đang quản lý, xem và xuất đúng phạm vi đã chọn.',`<button class="btn" data-action="export" ${r.rows.length?'':'disabled'}>${icon('download')}Xuất CSV</button><button class="btn primary" data-action="print" ${r.rows.length?'':'disabled'}>${icon('print')}In / Lưu PDF</button>`)+toolbar(filterSelect('type','Loại báo cáo',[['catalog','Danh mục & tình trạng tài sản'],['loans','Mượn / trả thiết bị'],['maintenance','Chi phí bảo trì']],f.type)+(f.type==='catalog'?filterSelect('unit','Đơn vị',[['','Tất cả đơn vị'],...(server?server.departments.map(d=>[d.name,d.name]):[...new Set(db.assets.map(a=>a.unit))].map(u=>[u,u]))],f.unit):field('from',f.type==='loans'?'Ngày mượn từ':'Ngày hoàn tất từ',input('from','date',f.from))+field('to','Đến ngày',input('to','date',f.to))))+`<p class="results-line">Quyền demo: Xem báo cáo · Xuất báo cáo</p><section class="panel report-document"><div class="report-summary"><div><span class="eyebrow">ĐẠI HỌC HẢI PHÒNG · PHÒNG & TÀI SẢN</span><h2>${r.title}</h2><p>${f.type==='catalog'?esc(f.unit||'Tất cả đơn vị'):`Từ ${f.from?fmtDate(f.from):'đầu dữ liệu'} đến ${f.to?fmtDate(f.to):'hiện tại'}`}</p></div></div>${table(r.headers,r.rows.map(row=>row.map(v=>typeof v==='number'?new Intl.NumberFormat('vi-VN').format(v):esc(v))))}<div class="report-note">${r.note}</div></section><p class="print-only">Dữ liệu demo · Xuất ${stamp(new Date().toISOString())} · Không thay thế chứng từ chính thức.</p>`;}
function render(){latest();route=location.hash.replace(/^#\//,'')||'overview';if(server&&!menus.some(m=>m[0]===route))route='overview';const m=menus.find(m=>m[0]===route);$('#nav').innerHTML=menus.map(([id,i,label],index)=>`${index===1?'<p class="nav-caption">PHÒNG & SỬ DỤNG</p>':index===5?'<p class="nav-caption">TÀI SẢN & VẬN HÀNH</p>':''}<a class="nav-link ${route===id?'active':''}" href="#/${id}" ${route===id?'aria-current="page"':''}>${icon(i)}${label}${id==='approvals'&&!server?`<span class="nav-count">${db.requests.filter(r=>r.status==='pending').length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=m?.[2]||'Không tìm thấy';document.title=(m?.[2]||'Không tìm thấy')+' · Quản lý phòng & tài sản HPUNI';const views={overview:server?serverOverview:overview,rooms,calendar,approvals,loans,assets,inventory,maintenance,logs,reports};if(server&&route==='lifecycle')views.lifecycle=()=>{queueMicrotask(()=>mountAssetLifecycle(document.querySelector('#asset-lifecycle')).catch(e=>toast(e.message)));return '<section class="panel" id="asset-lifecycle" style="padding:24px"></section>';};if(server&&route==='reports')views.reports=()=>{queueMicrotask(()=>mountReports(document.querySelector('#server-reports'),{finance:false}));return heading('Báo cáo quản trị','Tổng hợp dữ liệu thật, giới hạn theo quyền và phạm vi tài khoản.')+'<section class="panel" id="server-reports"></section>';};$('#main').innerHTML=(storageIssue?`<div class="error-banner" role="alert">${esc(storageIssue)} Các thao tác ghi đang tạm khóa.</div>`:'')+(views[route]?views[route]():heading('Không tìm thấy trang','Chọn chức năng từ menu để tiếp tục.')+'<a class="btn primary" href="#/overview">Về tổng quan</a>');if(server&&server.pageInfo){const p=server.pageInfo;$('#main').insertAdjacentHTML('beforeend',`<div class="list-toolbar" aria-label="Phân trang"><button class="btn" data-action="resource-page" data-id="${p.page-1}" ${p.page<=1?'disabled':''}>Trang trước</button><span>Trang ${p.page} / ${Math.max(1,Math.ceil(p.total/p.pageSize))} · ${p.total} hồ sơ theo bộ lọc</span><button class="btn" data-action="resource-page" data-id="${p.page+1}" ${p.page*p.pageSize>=p.total?'disabled':''}>Trang sau</button></div>`);}menu(false);}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal();}
function form(op,id,body,label='Lưu thông tin',extra=''){return `<form data-operation="${op}" data-id="${esc(id)}" data-revision="${db.resourceRevision}">${body}<p class="error" id="form-error" role="alert"></p><div class="form-actions">${btn('Đóng','close')}${extra}<button class="btn primary" type="submit" ${storageIssue?'disabled':''}>${icon('check')}${label}</button></div></form>`;}
function detailGrid(rows){return `<dl class="detail-grid">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
function requestDetail(id,mode=''){
  latest();const r=db.requests.find(r=>r.id===id);if(!r)return toast('Không tìm thấy phiếu.');
  const fields=[['Mã phiếu',esc(r.id)],['Trạng thái',badge(r.status)],['Nguồn lực',esc(r.name)],['Người đăng ký',esc(r.ownerName||'Nguyễn Minh Anh · Khoa CNTT')],['Ngày sử dụng',fmtDate(r.date)],['Thời gian',`${r.start}–${r.end}`],[r.kind==='room'?'Số người':'Số lượng',r.students||r.quantity],['Mục đích',esc(r.purpose)]];
  let body=detailGrid(fields)+(overdue(r)?'<p class="alert-box">Phiếu đã quá hạn trả và còn thiết bị chưa được tiếp nhận.</p>':'');
  if(r.kind==='device')body+=`<div class="quantity-summary"><span>Đã mượn: <b>${r.quantity}</b></span><span>Đã xử lý trả: <b>${r.returned||0}</b></span><span>Còn giữ: <b>${r.quantity-(r.returned||0)}</b></span></div>`;
  if(r.reason)body+=`<p class="detail-note break">Ý kiến xét duyệt: ${esc(r.reason)}</p>`;
  if(r.handover)body+=`<div class="resource-history"><strong>Biên bản bàn giao</strong><p>${r.handover.quantity} thiết bị · ${stamp(r.handover.at)}<br>${esc(r.handover.condition)}</p></div>`;
  if(r.returnHistory?.length)body+=`<div class="resource-history"><strong>Lịch sử tiếp nhận trả</strong>${r.returnHistory.map(h=>`<p>${stamp(h.at)} · ${h.good} tốt, ${h.damaged} hỏng, ${h.lost} mất${h.overdue?' · Trả quá hạn':''}<br>${esc(h.notes)}</p>`).join('')}</div>`;
  if(mode==='reminder')body+=form('reminder',r.id,field('notes','Nội dung nhắc việc nội bộ',area('notes',r.reminder?.notes||''))+'<p class="form-note">Chỉ lưu nhắc việc trên trình duyệt; không gửi email hoặc tin nhắn.</p>','Lưu nhắc việc');
  else if(r.status==='pending'&&(!server||resourceAllows(identity,'requests.review',r.api.departmentId,r.api.ownerId)))body+=form('review',r.id,`<div class="decision-tabs"><label><input type="radio" name="status" value="approved" checked>Phê duyệt</label><label><input type="radio" name="status" value="rejected">Từ chối</label></div>`+field('notes','Ý kiến xét duyệt / lý do từ chối (không bắt buộc)',area('notes'))+'<p class="form-note">Hệ thống kiểm tra lại trạng thái, lịch bảo trì và phần khả dụng trước khi duyệt.</p>','Xác nhận xét duyệt');
  else if(r.kind==='device'&&r.status==='approved'&&(!server||resourceAllows(identity,'resources.manage',r.manageDepartmentId||r.api.departmentId,r.api.ownerId)))body+=form('handover',r.id,`<h3 class="form-section-title">Ghi nhận bàn giao thực tế</h3><div class="form-grid">${field('quantity','Số lượng thực giao *',input('quantity','number',r.quantity,`min="1" max="${r.quantity}" required`))}${field('notes','Tình trạng / phụ kiện bàn giao (không bắt buộc)',area('notes'),true)}</div><p class="form-note">Phiếu chuyển sang chờ người mượn xác nhận. Cán bộ không xác nhận nhận thay giảng viên.</p>`,'Lưu biên bản bàn giao');
  else if(r.status==='return_pending'&&(!server||resourceAllows(identity,'resources.manage',r.manageDepartmentId||r.api.departmentId,r.api.ownerId))){
    const q=r.returnRequest;body+=`<p class="detail-note">Tự khai: ${q.good} tốt, ${q.damaged} hỏng, ${q.lost} mất.<br>Ghi chú: ${esc(q.notes||'Không có')}</p>`+form('return',r.id,`<h3 class="form-section-title">Kết quả kiểm tra thực tế</h3><div class="form-grid">${[['good','Thiết bị tốt',q.good],['damaged','Hỏng / chờ xử lý',q.damaged],['lost','Báo mất đã xác minh',q.lost]].map(([n,l,v])=>field(n,l,input(n,'number',v,`min="0" max="${r.quantity-(r.returned||0)}" required`))).join('')}${field('notes','Biên bản tiếp nhận / giải trình khác tự khai (không bắt buộc)',area('notes',q.notes||''),true)}</div><p class="form-note">Thiết bị tốt trở lại khả dụng. Thiết bị hỏng và mất được tách khỏi số tốt để cho mượn. Phần chưa tiếp nhận vẫn thuộc phiếu mượn; giảng viên có thể gửi yêu cầu trả tiếp.</p>`,'Xác nhận tiếp nhận trả');
  }else body+=`<div class="form-actions">${overdue(r)?btn('Ghi nhắc việc nội bộ','reminder',r.id):''}${btn('Đóng phiếu','close')}</div>`;
  modal('Chi tiết đăng ký & xử lý',body);
}
function roomForm(id){latest();const r=db.catalog.rooms.find(r=>r.id===id);modal(r?'Cập nhật phòng':'Thêm phòng',form('room',r?.id||'',`<div class="form-grid">${field('id','Mã phòng *',input('id','text',r?.id||'','maxlength="30" required '+(r?'readonly':'')))}${field('name','Tên phòng *',input('name','text',r?.name||'','maxlength="150" required'))}${server?field('departmentId','Đơn vị sở hữu *',select('departmentId',departmentsFor('resources.manage',server.departments).filter(d=>d.active).map(d=>[d.id,d.name]),r?.api.departmentId||identity.departmentId)):field('building','Tòa nhà *',input('building','text',r?.building||'','maxlength="60" required'))}${field('seats','Sức chứa *',input('seats','number',r?.seats||40,'min="1" max="1000" required'))}${field('type','Loại phòng',select('type',['Phòng học','Phòng máy','Hội trường','Phòng thí nghiệm'].map(v=>[v,v]),r?.type||'Phòng học'))}${field('available','Tình trạng phục vụ',select('available',[['true','Đang phục vụ'],['false','Ngừng phục vụ']],String(r?.available??true)))}${field('tags','Tiện ích (cách nhau bằng dấu phẩy)',input('tags','text',r?.tags.join(', ')||'','maxlength="500"'),true)}</div><p class="form-note">Không giảm sức chứa dưới nhu cầu hoặc ngừng phục vụ khi còn lịch hiệu lực. Các cập nhật được phản ánh ở tra cứu phòng của giảng viên.</p>`));}
function assetForm(id){latest();const a=db.assets.find(a=>a.id===id);modal(a?'Cập nhật hồ sơ tài sản':'Ghi tăng tài sản',form('asset',a?.id||'',`<div class="form-grid">${field('id','Mã tài sản *',input('id','text',a?.id||'','maxlength="30" required '+(a?'readonly':'')))}${field('name','Tên tài sản *',input('name','text',a?.name||'','maxlength="150" required'))}${field('unit','Đơn vị quản lý *',input('unit','text',a?.unit||'Phòng Quản trị','maxlength="100" required'))}${field('location','Vị trí quản lý tài sản *',input('location','text',a?.location||'','maxlength="150" required'))}${field('quantity','Số lượng theo sổ *',input('quantity','number',a?.quantity||1,'min="1" max="100000" required'))}${field('price','Nguyên giá một đơn vị (đồng) *',input('price','number',a?.price||0,'min="0" max="1000000000000" required'))}${field('purchased','Ngày ghi tăng *',input('purchased','date',a?.purchased||TODAY,'required'))}${!a?.device?field('room','Phòng cố định (nếu có)',select('room',[['','Không gắn phòng'],...db.catalog.rooms.map(r=>[r.id,r.name])],a?.room||'')):''}${!a?field('loanable','Cho phép đăng ký mượn',select('loanable',[['false','Chỉ quản lý hồ sơ'],['true','Đưa vào danh mục cho mượn']],'false')):''}</div><p class="form-note">Đây là vị trí lưu hồ sơ quản lý tài sản, không phải trường bắt buộc khi giảng viên mượn. Không giảm số lượng dưới phần hỏng, mất và đang giữ/mượn.</p>`));}
function assetDetail(id){latest();const a=db.assets.find(a=>a.id===id);if(!a)return;modal('Hồ sơ tài sản',detailGrid([['Mã tài sản',esc(a.api?.code||a.id)],['Tên',esc(a.name)],['Đơn vị',esc(a.unit)],['Vị trí',esc(a.location)],[server?'Ngày mua':'Ngày ghi tăng',fmtDate(a.purchased)],[server?'Tổng nguyên giá nhóm':'Nguyên giá / đơn vị',money(a.price)],['Theo sổ',a.quantity],...(server?[["Nguồn hình thành",esc(a.api.acquisitionSource||'Chưa kê khai')],["Hồ sơ tham chiếu",esc(a.api.acquisitionReference||'Chưa kê khai')],["Đang mượn",a.api.outstanding],["Có thể cho mượn",a.api.availableNow]]:[]),['Hỏng / mất',`${a.unusable} hỏng · ${a.lost} mất`]])+`<p class="detail-note">${a.device?'Có liên kết với danh mục thiết bị cho mượn.':a.room?'Liên kết phòng '+esc(a.room)+'.':'Quản lý hồ sơ tài sản.'}</p><h3 class="form-section-title">Lịch sử bảo trì</h3>${db.maintenance.filter(m=>m.asset===id).map(m=>`<p class="subline">${esc(m.id)} · ${stamp(m.start)} · ${labels[m.status]}</p>`).join('')||(server?'<p class="subline">Mở màn Bảo trì và tìm mã/tên tài sản để tra cứu lịch sử đầy đủ.</p>':'<p class="subline">Chưa có kế hoạch.</p>')}<div class="form-actions">${btn('Cập nhật','asset-edit',id)}${btn('Lập kế hoạch bảo trì','maintenance-new',id,true)}</div>`);}
function inventoryNew(){latest();modal('Lập đợt kiểm kê',form('inventory-create','',`<div class="form-grid">${field('name','Tên đợt kiểm kê *',input('name','text','','maxlength="150" required'),true)}${field('unit','Đơn vị',select('unit',(server?departmentsFor('inventory.manage',server.departments).filter(d=>d.active).map(d=>[d.name,d.name]):[['','Tất cả đơn vị'],...(server?server.departments.map(d=>[d.name,d.name]):[...new Set(db.assets.map(a=>a.unit))].map(u=>[u,u]))])))}${field('date','Ngày kiểm kê *',input('date','date',TODAY,'required'))}</div><p class="form-note">Lưu ảnh chụp tên tài sản và số lượng theo sổ tại thời điểm lập đợt để đối chiếu về sau.</p>`,'Lập đợt kiểm kê'));}
function inventoryOpen(id){latest();const inv=db.inventories.find(i=>i.id===id);if(!inv)return;const body=`<p class="snapshot-note">${esc(inv.name)} · ${esc(inv.unit)} · ${fmtDate(inv.date)}<br>Giải trình và ghi chú là thông tin không bắt buộc. Bỏ trống số thực tế nếu chưa kiểm tra.</p><div class="inventory-rows">${inv.rows.map((r,i)=>`<div class="inventory-row" data-inventory-row="${esc(r.id)}"><h3>${esc(r.name)}<small class="record-code">${esc(r.id)} · Theo sổ tại lập đợt: ${r.expected}</small></h3>${inv.status==='completed'?`<p class="subline">Thực tế: ${r.actual} · Chênh lệch: ${r.actual-r.expected} · ${esc(r.condition)}<br>${esc(r.notes)}</p>`:`<div class="form-grid">${field('actual-'+i,'Số lượng thực tế',input('actual-'+i,'number',r.actual??'','min="0"'))}${field('condition-'+i,'Tình trạng',select('condition-'+i,[['','Chưa kiểm tra'],['Tốt','Tốt'],['Hỏng / cần xử lý','Hỏng / cần xử lý'],['Mất / thiếu','Mất / thiếu']],r.condition))}${field('notes-'+i,'Giải trình / ghi chú',input('notes-'+i,'text',r.notes,'maxlength="1000"'),true)}</div>`}</div>`).join('')}</div>`;modal('Đối chiếu kiểm kê tài sản',inv.status==='completed'?body+`<div class="form-actions">${badge('completed')}${btn('Đóng','close')}</div>`:form('inventory-save',id,body,'Lưu tiến độ','<button class="btn" type="submit" name="finish" value="true">Hoàn tất đợt kiểm kê</button>'));}
function localTime(d){const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,16);}
async function openMaintenancePicker(id){
 const sourceRoute=route,selected=db.assets.find(a=>a.id===id),result=await server.pickAssets({page:1,search:''});
 if(route!==sourceRoute)return;
 db.assets=result.items;if(selected&&!db.assets.some(a=>a.id===selected.id))db.assets.unshift(selected);
 if($('#dialog').open)$('#dialog').close();maintenanceNew(id);
}

function maintenanceNew(id){latest();const a=db.assets.find(a=>a.id===id)||db.assets[0];if(!a)return toast('Chưa có tài sản để lập kế hoạch bảo trì.');modal('Lập kế hoạch bảo trì',form('maintenance-plan','',`<div class="form-grid">${field('asset','Tài sản *',select('asset',db.assets.map(a=>[a.id,a.name]),a.id),true)}${field('mode','Loại công việc',select('mode',[['service','Bảo trì thiết bị đang tốt'],['repair','Sửa chữa tài sản hỏng']],a.unusable?'repair':'service'))}${field('quantity','Số lượng *',input('quantity','number',a.unusable||1,'min="1" required'))}${field('start','Bắt đầu *',input('start','datetime-local',localTime(Date.now()),'required'))}${field('end','Kết thúc dự kiến *',input('end','datetime-local',localTime(Date.now()+3600000),'required'))}${field('content','Nội dung bảo trì (không bắt buộc)',area('content'),true)}</div><p class="form-note">Bảo trì phần đang tốt sẽ giữ số lượng theo lịch. Sửa phần hỏng không trừ hai lần khỏi số tốt. Tài sản liên kết phòng sẽ chặn lịch của phòng trong khoảng bảo trì.</p>`,'Lưu kế hoạch'));
 const initial=[...db.assets];mountAssetCombobox($('[data-operation=maintenance-plan] [name=asset]'),{items:initial,fetchPage:server?args=>server.pickAssets(args):async({page,search})=>{const filtered=initial.filter(a=>(a.name+' '+a.id).toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));return{items:filtered.slice((page-1)*20,page*20),total:filtered.length};},onChoose:a=>{if(!db.assets.some(row=>row.id===a.id))db.assets.push(a);}});
}
function maintenanceOpen(id){latest();const m=db.maintenance.find(m=>m.id===id);if(!m)return;
 const printLink=server?`<p class="form-note">${m.paymentStatus==='paid'?'Đã thanh toán · Chứng từ: '+esc(m.voucher):m.paymentRequestId?'Chờ kế toán thanh toán · Yêu cầu: '+esc(m.paymentRequestId):m.cost>0?'Chi phí cũ chưa chuyển hàng chờ; kế toán có thể nhập từ mã bảo trì.':'Không phát sinh chi phí.'}</p>`:`<a class="btn" target="_blank" rel="noopener" href="payment-voucher.html?maintenance=${encodeURIComponent(id)}">In chứng từ chi phí phát sinh</a>`;
 let body=detailGrid([['Mã kế hoạch',esc(m.id)],['Trạng thái',badge(m.status)],['Tài sản',esc(m.name)],['Số lượng',m.quantity],['Bắt đầu dự kiến',stamp(m.start)],['Kết thúc dự kiến',stamp(m.end)]])+`<p class="detail-note break">${esc(m.content)}</p>`;
 if(m.status==='planned')body+=form('maintenance-start',id,'<p class="form-note">Xác nhận khi thực tế bắt đầu bảo trì.</p>','Xác nhận bắt đầu');
 else if(m.status==='running')body+=form('maintenance-finish',id,`<div class="form-grid">${field('result','Tình trạng sau bảo trì',select('result',[['good','Hoạt động tốt'],['unavailable','Chưa khả dụng']]))}${field('cost','Chi phí phát sinh (đồng) *',input('cost','number',m.cost||0,'min="0" step="1" required '+(m.costRecordedAt?'readonly':'')))}${field('notes','Kết quả thực hiện (không bắt buộc)',area('notes'),true)}</div><p class="form-note">Chi phí được chuyển vào yêu cầu chi của kế toán, chưa trừ ngân sách. Chi phí đã gửi kế toán được giữ nguyên để tránh lệch chứng từ.</p>`,'Hoàn tất bảo trì',m.costRecordedAt?printLink:'<button class="btn" type="submit" name="printCost" value="true">Lưu & in chứng từ chi phí phát sinh</button>');
 else body+=`<div class="decision-record"><strong>${m.result==='good'?'Hoạt động tốt':'Chưa khả dụng'}</strong><p>${esc(m.resultNotes)}</p><small>${stamp(m.finishedAt)} · ${money(m.cost)}</small></div><div class="form-actions">${btn('Đóng','close')}${m.cost>0?printLink:''}</div>`;
 modal('Theo dõi kế hoạch bảo trì',body);
}

function logOpen(id){latest();const l=db.logs.find(l=>l.id===id),r=db.requests.find(r=>r.id===l?.request);if(!l)return;let body=detailGrid([['Nhật ký',esc(l.id)],['Trạng thái',badge(l.status)],['Nguồn lực',esc(r?.name||l.request)],['Ngày sử dụng',fmtDate(l.date)],['Giờ đăng ký',r?`${r.start}–${r.end}`:'—'],['Giờ thực tế',`${l.start}–${l.end}`],['Số người đăng ký / thực tế',r?.kind==='room'?`${r.students} / ${l.students}`:'Không áp dụng'],['Tình trạng',esc(l.condition)]])+`<p class="detail-note break">Ghi chú: ${esc(l.notes||'Không có')}</p>`;if(l.status==='pending')body+=form('log',id,`<div class="decision-tabs"><label><input name="status" type="radio" value="confirmed" checked>Xác nhận</label><label><input name="status" type="radio" value="needs_update">Yêu cầu bổ sung</label></div>`+field('notes','Ý kiến đối chiếu / nội dung cần bổ sung (không bắt buộc)',area('notes')),'Lưu kết quả đối chiếu');else body+=`<p class="detail-note break">Ý kiến quản lý: ${esc(l.reviewNotes||'')}</p><div class="form-actions">${btn('Đóng','close')}</div>`;modal('Đối chiếu nhật ký sử dụng',body);}
function exportReport(){const r=reportData();if(!r.rows.length)return;const cell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const f=filters.reports,url=URL.createObjectURL(new Blob(['\uFEFF'+[[r.title],[f.type==='catalog'?f.unit||'Tất cả đơn vị':`${f.from||'Đầu dữ liệu'} → ${f.to||'Hiện tại'}`],r.headers,...r.rows,['Dữ liệu demo']].map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`HPUNI-nguon-luc-${f.type}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất báo cáo CSV theo bộ lọc.');}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t)return;const id=t.dataset.id;switch(t.dataset.action){case'menu':menu(!$('#sidebar').classList.contains('open'));break;case'close':e.preventDefault();$('#dialog').close();break;case'request':requestDetail(id);break;case'reminder':requestDetail(id,'reminder');break;case'room-new':roomForm();break;case'room-edit':roomForm(id);break;case'room-calendar':filters.calendar.room=id;location.hash='#/calendar';break;case'asset-new':assetForm();break;case'asset-edit':assetForm(id);break;case'asset-view':assetDetail(id);break;case'inventory-new':inventoryNew();break;case'inventory-open':inventoryOpen(id);break;case'maintenance-new':maintenanceNew(id);break;case'maintenance-open':maintenanceOpen(id);break;case'log-open':logOpen(id);break;case'export':exportReport();break;case'print':if(reportData().rows.length)window.print();break;case'notifications':modal('Công việc cần xử lý',`<a class="notice-link" href="#/approvals">${icon('file')}<span>Đăng ký chờ duyệt</span><b>${db.requests.filter(r=>r.status==='pending').length}</b></a><a class="notice-link" href="#/loans">${icon('equipment')}<span>Yêu cầu trả chờ tiếp nhận</span><b>${db.requests.filter(r=>r.status==='return_pending').length}</b></a><a class="notice-link" href="#/logs">${icon('book')}<span>Nhật ký chờ xác nhận</span><b>${db.logs.filter(l=>l.status==='pending').length}</b></a>`);break;case'profile':if(server){toast(identity.displayName);break;}modal('Cán bộ quản lý phòng và tài sản',detailGrid([['Vai trò','Quản lý phòng và tài sản'],['Phạm vi','Toàn trường (demo)'],['Phân hệ','Phòng học · Tài sản · Mượn / trả'],['Lưu dữ liệu','Trình duyệt hiện tại']])+'<p class="form-note">Chưa có đăng nhập, phân quyền máy chủ hoặc đồng bộ nhiều thiết bị. Chuyển không gian demo ở menu để thử luồng giảng viên và quản lý.</p>');break;case'help':modal('Hướng dẫn quản lý nguồn lực','<div class="detail-note"><p>1. Giảng viên gửi đăng ký; mở <b>Duyệt đăng ký</b> để xét duyệt sau khi kiểm tra lịch.</p><p>2. Với thiết bị đã duyệt, mở <b>Mượn / trả</b>, lập biên bản bàn giao; giảng viên tự xác nhận nhận.</p><p>3. Giảng viên gửi yêu cầu trả; cán bộ đối chiếu thực tế và tiếp nhận tốt/hỏng/mất. Hỗ trợ trả từng phần.</p><p>4. Tạo hồ sơ tài sản, lập đợt kiểm kê, ghi nhận đầy đủ và giải trình trước khi hoàn tất.</p><p>5. Lập kế hoạch bảo trì theo lịch, xác nhận bắt đầu, ghi kết quả và liên kết chứng từ mẫu nếu phát sinh chi phí.</p><p>6. Xác nhận nhật ký hoặc yêu cầu giảng viên bổ sung. Các báo cáo xuất CSV và in PDF theo bộ lọc.</p></div>');break;}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='filters'){e.preventDefault();return;}if(!f.dataset.operation)return;e.preventDefault();try{if(storageIssue)throw Error(storageIssue);const current=readResources(),p=Object.fromEntries(new FormData(f)),op=e.submitter?.name==='printCost'?'maintenance-cost':f.dataset.operation;const id=f.dataset.id||p.id;Object.assign(p,{id});if(op==='room'){p.available=p.available==='true';p.edit=!!f.dataset.id;}if(op==='asset'){p.edit=!!f.dataset.id;p.loanable=p.loanable==='true';}if(op==='inventory-save'){const inv=current.inventories.find(i=>i.id===id);p.rows=inv.rows.map((r,i)=>({id:r.id,actual:p['actual-'+i],condition:p['condition-'+i],notes:p['notes-'+i]}));p.finish=e.submitter?.name==='finish';}const next=manageResources(current,op,p,Number(f.dataset.revision));localStorage.setItem(RESOURCE_KEY,JSON.stringify(next));db=next;$('#dialog').close();render();if(op==='maintenance-cost'){maintenanceOpen(id);window.open('payment-voucher.html?maintenance='+encodeURIComponent(id),'_blank','noopener');}toast((actionLabels[op]||'Cập nhật')+' thành công.');}catch(err){$('#form-error').textContent=err.message||'Không thể lưu dữ liệu.';$('#form-error').scrollIntoView({block:'nearest'});}});
function updateFilters(target){if(!target.closest('#filters')||!filters[route])return;const f=filters[route];Object.assign(f,Object.fromEntries(new FormData($('#filters'))));if(f.from&&f.to&&f.from>f.to){toast('Ngày kết thúc phải từ ngày bắt đầu trở đi.');return;}const focus=target.id,pos=target.selectionStart;if(server){clearTimeout(resourceFilterTimer);resourceFilterTimer=setTimeout(async()=>{await loadResourceRoute(1);const el=document.getElementById(focus);el?.focus();if(el&&pos!==null&&el.type==='search')el.setSelectionRange(pos,pos);},target.name==='search'?250:0);return;}render();if(target.name==='search'){const el=document.getElementById(focus);el?.focus();if(el&&pos!==null)el.setSelectionRange(pos,pos);}}
document.addEventListener('change',e=>{updateFilters(e.target);if(e.target.name==='asset'&&e.target.closest('[data-operation=maintenance-plan]')){const a=db.assets.find(a=>a.id===e.target.value);$('#f-mode').value=a.unusable?'repair':'service';$('#f-quantity').value=a.unusable||1;}});
document.addEventListener('input',e=>{if(e.target.name==='search')updateFilters(e.target);});
$('#backdrop').addEventListener('click',()=>menu(false));
document.addEventListener('keydown',e=>{if(e.key==='Escape')menu(false);});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',async()=>{if($('#dialog').open)$('#dialog').close();if(server)await loadResourceRoute(1);else render();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key!==RESOURCE_KEY)return;latest();if($('#dialog').open){if($('#form-error'))$('#form-error').textContent='Dữ liệu đã cập nhật từ tab khác. Đóng và mở lại biểu mẫu trước khi lưu.';}else render();});
render();

if(server){if(route==='calendar')await server.availability(filters.calendar.date);installServerResources();render();}
